package com.bank.sharding.service;
import com.bank.sharding.model.ShardKey;
import java.util.*;
import java.util.logging.*;

public class ShardRouter {
    private static final Logger log = Logger.getLogger(ShardRouter.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final int shardCount;
    private final Map<String,Integer> directory = new HashMap<>();  // directory-based map
    public ShardRouter(int shardCount) { this.shardCount = shardCount; }

    // HASH: even distribution, single-key lookups easy, range queries scatter
    public int hashRoute(ShardKey k) {
        int shard = Math.floorMod(k.getAccountId().hashCode(), shardCount);
        log.info(() -> "HASH " + k.getAccountId() + " -> shard_" + shard);
        return shard;
    }
    // RANGE: easy range scans but monotonically increasing ids create a hot shard
    public int rangeRoute(ShardKey k) {
        int num = Integer.parseInt(k.getAccountId().replaceAll("\\D", ""));
        int shard = Math.min(num / 3334, shardCount - 1);   // id blocks per shard
        log.info(() -> "RANGE " + k.getAccountId() + " -> shard_" + shard + " (hot-shard risk on new ids)");
        return shard;
    }
    // DIRECTORY: explicit map, flexible placement, extra lookup per access
    public void place(ShardKey k, int shard) { directory.put(k.getAccountId(), shard); }
    public int directoryRoute(ShardKey k) {
        int shard = directory.getOrDefault(k.getAccountId(), -1);
        log.info(() -> "DIRECTORY " + k.getAccountId() + " -> shard_" + shard);
        return shard;
    }
}
