package com.bank.sharding;
import com.bank.sharding.model.ShardKey;
import com.bank.sharding.service.ShardRouter;
import java.util.logging.*;

public class ShardDemo {
    public static void main(String[] args) {
        ShardRouter router = new ShardRouter(3);
        ShardKey rajesh = new ShardKey("SAV2001");
        ShardKey priya = new ShardKey("CUR3001");
        router.hashRoute(rajesh);
        router.hashRoute(priya);
        router.rangeRoute(rajesh);
        router.place(rajesh, 2);           // directory placement
        router.directoryRoute(rajesh);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
